#!/bin/bash
# cyclicfocus.sh PREVCHECK "changes since then" : print the lens-10 focus (fifth-run focus + CYCLIC CHECK) using the versions archived by siblings.sh.
M=/home/user/claude_composes/symphony/scherzo
V1=$(ls /tmp/siblings/mvt1 | grep -E '^v[0-9]+$'); V2=$(ls /tmp/siblings/mvt2 | grep -E '^v[0-9]+$'); V3=$(ls /tmp/siblings/mvt3 | grep -E '^v[0-9]+$')
echo "$(cat $M/kit/focus-fifth.txt) CYCLIC CHECK: the other movements' current versions are copied at /tmp/siblings/mvt1/$V1 (movement I), /tmp/siblings/mvt2/$V2 (movement II) and /tmp/siblings/mvt3/$V3 (finale); all three are in their own fifth runs. Their owners' newest records are in /tmp/siblings/coherence/ (file suffix = branch: 6v70nw movement I, sgcp3g movement II, gvpxu4 finale; read each owner's own file, e.g. mvt1.md.6v70nw, mvt2.md.sgcp3g, finale.md.gvpxu4, themes-finale-quotes.ly.gvpxu4). Use symphony/coherence/themecheck.py (checks 'abs' lines at pitch; --beats 4 for movement I and the finale; movement II's themes-mvt2.ly is in 3/4, use the default beats). Scherzo changes since the $1 check: $2 Check the joins (movement II's end into bar 1; bar 376 into the finale's bar 1), all finale quotations (IV 1, 9, 143-145, 178, 219-220, 243, 272-277), movement I's links (T's head, motive-x chain, I 79), and whether coherence/scherzo.md is current (the composer updates it at this cycle); name any message the scherzo thread must send."
